// ** React Imports
import React, { Fragment } from 'react';

// ** Third Party Components
import ReactSelect from 'react-select';

// ** Reactstrap Imports
import { FormFeedback, Label } from 'reactstrap';
import { customFilterOption, customGetOptionLabel } from 'utils/commonFunc';

export const requiredIcon = (
  <span style={{ color: 'red' }}>
    <sup>*</sup>
  </span>
);

const CommonSelect = props => {
  const {
    noLabel = false,
    name = '',
    label = 'Select',
    defaultValue = null,
    value = null,
    options = [],
    isClearable = false,
    onSelect,
    onChange,
    placeholder = 'Select...',
    isRequired = false,
    isMulti = false,
    error = '',
    style = null,
    disabled,
    onInputChange,
    applyLabelStyle = false,
    loading = false,
  } = props;
  return (
    <Fragment>
      {!noLabel && (
        <Label className="form-label">
          {label} {isRequired && requiredIcon}
        </Label>
      )}
      <ReactSelect
        className="react-select"
        classNamePrefix="select"
        defaultValue={defaultValue}
        value={options?.find(el => el.value === value) || null}
        options={options}
        isClearable={isClearable}
        onChange={item => {
          if (!item || item?.value !== value) {
            onSelect && onSelect(name, item?.value || null);
            onChange && onChange(name, item?.value || null);
          }
        }}
        placeholder={placeholder}
        isMulti={isMulti}
        styles={{
          control: provided => ({
            ...provided,
            ...(error && { borderColor: '#c62828' }),
            ...(style && { ...style }),
          }),
        }}
        isDisabled={disabled}
        onInputChange={text => {
          onInputChange?.(text);
        }}
        getOptionLabel={applyLabelStyle ? customGetOptionLabel : undefined}
        filterOption={applyLabelStyle ? customFilterOption : undefined}
        isLoading={loading}
      />
      {error && <FormFeedback>{error}</FormFeedback>}
    </Fragment>
  );
};

export default CommonSelect;
