import { makeFirstCaps } from 'config/constants';
import React from 'react';

export const ActiveSpan = ({ status = 'Active', style }) => {
  return (
    <span className="active-span" style={style}>
      {makeFirstCaps(status)}
    </span>
  );
};

export const DeactiveSpan = ({ status = 'Deactive' }) => {
  return <span className="deactive-span">{makeFirstCaps(status)}</span>;
};
