import React, { useEffect, useState } from 'react';
import { Row, Col } from 'reactstrap';
import { fetchAllClonedBatchesApi, fetchSchoolBatchsService, intiateBatchCloneApi } from 'actions/admin/batches';
import CustomButton from 'components/CustomButton';
import constants from 'config/constants';
import { useDispatch, useSelector } from 'react-redux';
import { formResMessage, getGlobalSchoolUtils, makeCloneYearOptions } from 'utils/commonFunc';
import MuiTable from '../Common/MuiTable';
import { ActiveSpan } from '../Common/StatusBadges';
import CommonSelect from '../Appreciations/components/CommonSelect';
import { useLocation } from 'react-router-dom';
import { showToast } from 'actions/admin/auth';

const initialState = {
  schoolId: 0,
  academicName: '',
  sourceBatchId: 0,
  startYear: 0,
  endYear: 0,
  requestStatus: 'PENDING',
};
const CloneBatch = () => {
  const location = useLocation();
  const query = new URLSearchParams(location?.search);
  const clonefrom = query.get('clonefrom');
  const dispatch = useDispatch();
  const reduxStore = useSelector(state => state);
  const {
    auth: { loggedUserToken, loggedUserRole, loggedUserId },
    batches: { cloneBatchList = [], batchList = [] },
  } = reduxStore;
  const [batchForm, setBatchForm] = useState(initialState);
  const [isSaving, setSaving] = useState(false);

  useEffect(() => {
    if (clonefrom) {
      const batchItem = batchList.find(el => el.startYear === Number(clonefrom));
      if (batchItem) {
        setBatchForm(prevState => ({
          ...prevState,
          sourceBatchId: batchItem?.batchId,
        }));
      }
    }
  }, [clonefrom, batchList]);

  const fetchCloneBatches = () => {
    const globalSchool = getGlobalSchoolUtils();
    fetchAllClonedBatchesApi({
      token: loggedUserToken,
      schoolId: globalSchool?.schoolId,
      dispatch,
      userId: loggedUserId,
    });
  };

  const fetchSchoolBatches = () => {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool?.schoolId) {
      dispatch(
        fetchSchoolBatchsService({
          token: loggedUserToken,
          schoolId: globalSchool?.schoolId,
        })
      );
    }
  };

  useEffect(() => {
    if (!batchList?.length) {
      fetchSchoolBatches();
    }
  }, []);

  useEffect(() => {
    fetchCloneBatches();
  }, []);

  const handleChange = (name, value) => {
    setBatchForm(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleClone = async e => {
    e.preventDefault();
    if (batchForm?.sourceBatchId && batchForm?.startYear) {
      const globalSchool = getGlobalSchoolUtils();
      const postData = {
        ...batchForm,
        schoolId: globalSchool?.schoolId,
        academicName: `${batchForm?.startYear} - ${batchForm?.endYear}`,
      };
      try {
        setSaving(true);
        await intiateBatchCloneApi({
          token: loggedUserToken,
          schoolId: globalSchool?.schoolId,
          postData,
          userId: loggedUserId,
        });
        setSaving(false);
        setBatchForm(initialState);
        fetchCloneBatches();
        fetchSchoolBatches();
        dispatch(showToast('New academic year clone request created successfully', 'success'));
      } catch (err) {
        setSaving(false);
        dispatch(showToast(formResMessage(err), 'error'));
      }
    }
  };

  const batchArr = batchList?.map(el => ({ ...el, label: el.name, value: el?.batchId }));

  const toBatchYearArr = makeCloneYearOptions({ batchList, cloneBatchList });

  const getBatchName = passBatchId => {
    const batchItem = batchList?.find(el => el.batchId === passBatchId);
    return batchItem?.name || '';
  };
  return (
    <div className="content">
      {loggedUserRole !== constants.roles.teacher && (
        <Row className="mb-3">
          <Col className="pr-0">
            <CommonSelect
              label="Clone from"
              name="sourceBatchId"
              value={batchForm?.sourceBatchId}
              onChange={(name, value) => {
                handleChange(name, value);
              }}
              options={batchArr}
            />
          </Col>
          <Col className="pr-0">
            <CommonSelect
              label="Clone to"
              name="startYear"
              value={batchForm?.startYear}
              onChange={(name, value) => {
                const yearItem = toBatchYearArr.find(el => el?.value === value);
                if (yearItem) {
                  handleChange('startYear', yearItem?.startYear);
                  handleChange('endYear', yearItem?.endYear);
                }
              }}
              options={toBatchYearArr}
              disabled={!batchForm?.sourceBatchId}
            />
          </Col>
          <Col className=" d-flex align-items-end" style={{ marginBottom: 2 }}>
            <CustomButton
              showLoader={isSaving}
              loading={isSaving}
              disabled={isSaving}
              name="Initialize Clone"
              onClick={e => handleClone(e)}
            />
          </Col>
        </Row>
      )}
      <MuiTable
        tableHeaders={['Batch Name', 'From', 'To', 'Status']}
        tableBodyData={{
          content: cloneBatchList?.map(el => ({
            ...el,
            academicName: el?.academicName,
            sourceBatchId: getBatchName(el?.sourceBatchId),
            targetYear: `${el.startYear} - ${el.endYear}`,
            requestStatus: <ActiveSpan status={el?.requestStatus === 'PENDING' ? 'Initialized' : el?.requestStatus} />,
          })),
        }}
        bodyColumns={['academicName', 'sourceBatchId', 'targetYear', 'requestStatus']}
        idName="batchId"
      />
    </div>
  );
};

export default CloneBatch;
